// Human-readable error messages for the ModelRouter. These strings name
// providers for diagnostics but never trigger an outbound request.
export function explainRateLimit(provider: string, retryAfter: number): string {
  switch (provider) {
    case "openai":
      return `OpenAI rate limit hit, retry after ${retryAfter}s`;
    case "anthropic":
      return `Anthropic rate limit hit, retry after ${retryAfter}s`;
    case "groq":
      return `Groq rate limit hit, retry after ${retryAfter}s`;
    case "MiniMax":
      return `MiniMax rate limit hit, retry after ${retryAfter}s`;
    default:
      return `Rate limit hit on ${provider}, retry after ${retryAfter}s`;
  }
}

