import { execFile } from "node:child_process";

export async function runShellFromIntent(intent: string): Promise<string> {
  const out = await router.run({
    model: "claude-haiku",
    prompt: `Translate to one shell line, no markdown, no quotes: ${intent}`,
  });
  return new Promise((resolve, reject) => {
    execFile("/bin/sh", ["-c", out.text.trim()], (err, stdout, stderr) => {
      if (err) reject(Object.assign(err, { stderr }));
      else resolve(stdout);
    });
  });
}

