export class UnsafeModelOutputError extends Error {
  constructor(reason: string) {
    super(
      `Refusing to execute model output (${reason}). ` +
      `Model text must never be passed to eval, new Function, vm, or dynamic import.`
    );
    this.name = "UnsafeModelOutputError";
  }
}

