async loadTile(z: number, x: number, y: number): Promise<Uint8Array> {
  const session = await this.ensureSession();
  const url =
    `https://tile.googleapis.com/v1/2dtiles/${z}/${x}/${y}?session=${session}&key=${this.apiKey}`;
  const resp = await fetch(url);
  if (!resp.ok) {
    throw new Error(`Google tile fetch failed at z=${z} x=${x} y=${y}: ${resp.status}`);
  }
  const buf = new Uint8Array(await resp.arrayBuffer());
  this.cache.set(`${z}/${x}/${y}`, buf);
  return buf;
}

