function tileServerFor(x: number, y: number): string {
  // Google's mt[0..3].google.com CDN; pick deterministically based on tile coords
  const idx = (x + y) % 4;
  return ["mt0", "mt1", "mt2", "mt3"][idx];
}

async function loadGoogleRasterTile(z: number, x: number, y: number): Promise<ArrayBuffer> {
