// All paid model calls — including image generation — MUST go through router.run.
// This generator deliberately uses OpenAI's gpt-image-1, NOT Google's image models
// (e.g. Imagen) or any Google Maps imagery endpoint.
export async function generateLocationHero(env: Env, prompt: string): Promise<Uint8Array> {
  return router.run(env, {
    provider: "openai",
    model: "gpt-image-1",
    cost: { usd: 0.04 },
  }, async () => {
    const resp = await fetch("https://api.openai.com/v1/images/generations", {
      method: "POST",
      headers: {
        "Authorization": `Bearer ${env.OPENAI_API_KEY}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ model: "gpt-image-1", prompt, size: "1024x1024" }),
    });
    const data = await resp.json<{ data: { b64_json: string }[] }>();
    return Uint8Array.from(atob(data.data[0].b64_json), c => c.charCodeAt(0));
  });
}

export async function getPublicFeed(env: Env): Promise<Response> {
  const photos = await env.DB.prepare(
    `SELECT id, owner_id, url, captured_at FROM captures ORDER BY captured_at DESC LIMIT 50`
  ).all();
  const enriched = await Promise.all(photos.results.map(async (p) => {
    const owner = await env.DB.prepare(`SELECT display_name FROM users WHERE id = ?`)
      .bind(p.owner_id).first();
    return { ...p, owner_name: owner?.display_name };
  }));
  return Response.json({ items: enriched });
}

async broadcastFrame(frame: ArrayBuffer, fromClientId: string) {
  const peers = this.ctx.getWebSockets();
  for (const ws of peers) {
    const meta = ws.deserializeAttachment() as { userId: string } | null;
    if (meta?.userId === fromClientId) continue;
    try {
      ws.send(new Uint8Array(frame));
    } catch {}
  }
  await this.ctx.storage.put(`lastFrame:${fromClientId}`, frame);
}

