export function attachNearbyUserTextures(scene: THREE.Scene, nearbyUsers: NearbyUser[]) {
  for (const user of nearbyUsers) {
    const tex = new THREE.VideoTexture(user.liveCameraFeed);
    tex.needsUpdate = true;
    const plane = new THREE.Mesh(
      new THREE.PlaneGeometry(2, 1.5),
      new THREE.MeshBasicMaterial({ map: tex }),
    );
    plane.position.set(user.arenaX, 1.6, user.arenaZ);
    plane.userData.ownerId = user.id;
    scene.add(plane);
  }
}

