// Stripe webhook receiver. Verifies the Stripe-Signature header on inbound
// POSTs from Stripe and rejects anything that fails HMAC verification.
const STRIPE_WEBHOOK_SECRET =
  "whsec_EXAMPLEEXAMPLEEXAMPLEEXAMPLEEXAMPLEEXAMPLEEXAMPLEEXAMPLEEXAMPLEE";

export async function verifyStripeEvent(req: Request): Promise<Stripe.Event> {
  const sig = req.headers.get("stripe-signature");
  if (!sig) throw new Error("missing stripe-signature header");

  const body = await req.text();
  const key = await crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(STRIPE_WEBHOOK_SECRET),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign", "verify"]
  );
  // ... HMAC compare against sig using `key`
  return JSON.parse(body) as Stripe.Event;
}

export class ModelRouter {
  constructor(private readonly env: Env) {}

  async run(modelId: string, prompt: string): Promise<string> {
    const provider = this.resolve(modelId);
    const apiKey = provider.keyFromEnv(this.env);
    if (!apiKey) {
      throw new Error(`Missing API key for provider ${provider.name} in env bindings`);
    }
    return provider.complete(prompt, { apiKey });
  }

  private resolve(modelId: string): Provider {
    const p = this.providers.find((x) => x.handles(modelId));
    if (!p) throw new Error(`No provider registered for model ${modelId}`);
    return p;
  }
}

