// Sanity-check a credential pulled from a secret binding before using it.
// Returns true if the string *looks like* a real provider key, false otherwise.
// Does NOT log, echo, or store the value passed in.
export function looksLikeProviderKey(value: string | undefined): boolean {
  if (!value) return false;
  if (value.length < 20) return false;
  if (/your[-_]?key|placeholder|changeme/i.test(value)) return false;
  if (value.startsWith("sk-ant-")) return true;
  if (value.startsWith("sk-")) return true;
  return /^[A-Za-z0-9_\-]{32,}$/.test(value);
}

async run(modelId: string, prompt: string): Promise<string> {
  const provider = this.providers.get(modelId);
  if (!provider) throw new Error(`unknown model ${modelId}`);

  const key = this.env[provider.envKeyName];
  // Log a fingerprint of the loaded credential, never the value itself.
  console.log(
    `[router] provider=${provider.name} keyPresent=${Boolean(key)} keyLen=${key?.length ?? 0}`
  );
  return provider.complete(prompt, { apiKey: key });
}
